import * as cdk from 'aws-cdk-lib/core';
import { Construct } from 'constructs';
import * as secretsmanager from 'aws-cdk-lib/aws-secretsmanager';

export interface AuthSecretProps {
  readonly isLocal: boolean;
}

// HS256 signing key for session JWTs, generated by CloudFormation on deploy.
export class AuthSecret extends Construct {
  readonly secret: secretsmanager.Secret;

  constructor(scope: Construct, id: string, props: AuthSecretProps) {
    super(scope, id);

    this.secret = new secretsmanager.Secret(this, 'JwtSigningKey', {
      description: 'HS256 signing key for session JWTs',
      generateSecretString: {
        passwordLength: 64,
        excludePunctuation: true,
      },
      removalPolicy: props.isLocal
        ? cdk.RemovalPolicy.DESTROY
        : cdk.RemovalPolicy.RETAIN,
    });
  }
}
